(function(root){'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=x=>String(x||'funcionario').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').toLowerCase();
const fieldNames={name:'Nome',address:'Endereço',phone:'Telefone',birthDate:'Nascimento',age:'Idade',role:'Função',cpf:'CPF',rg:'RG',admissionDate:'Admissão',companyStatus:'Vínculo',spreadsheetNote:'Observações',category:'Categoria',employmentStatus:'Situação'};
const mime=x=>String(x||'').toLowerCase();
async function bytesOf(meta){const [file]=await root.LocalFiles.load([meta.id]);if(!file?.dataURL)throw Error('Não foi possível abrir o anexo '+meta.name);const base64=file.dataURL.split(',')[1];return Uint8Array.from(atob(base64),c=>c.charCodeAt(0));}
function downloadBytes(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function generatePdf(employee,include){if(!root.PDFLib)throw Error('Gerador de PDF indisponível.');const P=root.PDFLib;const doc=await P.PDFDocument.create(),regular=await doc.embedFont(P.StandardFonts.Helvetica),bold=await doc.embedFont(P.StandardFonts.HelveticaBold);let page=doc.addPage([595,842]),y=785;const text=(value,x,yy,font=regular,size=10)=>page.drawText(String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e]/g,' '),{x,y:yy,size,font,color:P.rgb(.15,.23,.35),maxWidth:480});text('ENGEFEX - FICHA DO FUNCIONARIO',42,y,bold,16);y-=42;text(employee.name,42,y,bold,14);y-=33;for(const [key,label] of Object.entries(fieldNames)){if(y<75){page=doc.addPage([595,842]);y=790}text(label+':',43,y,bold,10);text(employee[key]||'-',175,y);y-=27}
const attachments=employee.attachments||[];if(include&&attachments.length){page=doc.addPage([595,842]);y=786;text('DOCUMENTOS ANEXADOS',42,y,bold,16);y-=30;for(const meta of attachments){const type=mime(meta.type),name=meta.name||'Anexo';let data;try{data=await bytesOf(meta)}catch(err){throw Error('Falha ao incluir '+name+': '+err.message)}
if(type==='application/pdf'||/\.pdf$/i.test(name)){try{const source=await P.PDFDocument.load(data);const pages=await doc.copyPages(source,source.getPageIndices());pages.forEach(p=>doc.addPage(p))}catch(err){throw Error('O PDF anexo '+name+' não pôde ser incorporado: '+err.message)}continue;}
if(type.startsWith('image/')||/\.(png|jpe?g)$/i.test(name)){let img;try{img=type.includes('png')||/\.png$/i.test(name)?await doc.embedPng(data):await doc.embedJpg(data)}catch(err){throw Error('Imagem não suportada: '+name)}page=doc.addPage([595,842]);text(name,42,790,bold,11);const scale=Math.min(510/img.width,720/img.height);page.drawImage(img,{x:42,y:755-img.height*scale,width:img.width*scale,height:img.height*scale});continue}
if(y<100){page=doc.addPage([595,842]);y=790}text(name+' (anexo nao incorporavel ao PDF)',42,y,regular,10);y-=23;
}}
downloadBytes(await doc.save(),'ficha-'+normalize(employee.name)+(include?'-com-anexos':'')+'.pdf','application/pdf');}
const previous=root.EngefexRH.attach;
root.EngefexRH.attach=function(s,persist,render,notify){previous(s,persist,render,notify);if(!document.getElementById('hrSpreadsheet'))return;
document.querySelectorAll('.hr-actions-cell .button').forEach(button=>{if(button.textContent.trim()!=='Ficha completa')return;const cloned=button.cloneNode(true);button.replaceWith(cloned);const employeeId=cloned.parentElement?.querySelector('[data-hr-toggle]')?.dataset.hrToggle;const employee=(s.hrEmployees||[]).find(x=>x.id===employeeId);if(employee){const editOriginal=button.onclick;cloned.onclick=()=>open(employee,editOriginal);}});
function open(employee,editOriginal){const old=document.getElementById('hrAttachmentDialog');old?.remove();const d=document.createElement('dialog');d.id='hrAttachmentDialog';d.className='hr-editor hr-attachment-dialog';const all=employee.attachments||[];d.innerHTML='<div class="hr-editor-header"><div><small>ENGEFEX / RECURSOS HUMANOS</small><h2>'+esc(employee.name)+'</h2><p>Ficha individual e arquivos anexados</p></div><button class="hr-editor-close" data-close type="button">×</button></div><section class="hr-attachment-body"><div class="hr-profile-summary">'+Object.entries(fieldNames).map(([key,label])=>'<div><small>'+label+'</small><strong>'+esc(employee[key]||'—')+'</strong><button type="button" class="button secondary" data-copy="'+key+'">Copiar</button></div>').join('')+'</div><div class="hr-attachment-header"><div><h3>Documentos anexados</h3><p>PDF, imagens e outros arquivos de até 20 MB cada.</p></div><label class="button secondary">+ Anexar arquivos<input type="file" data-upload multiple hidden></label></div><div class="hr-attachment-list">'+(all.length?all.map((a,i)=>'<div class="hr-attachment-item"><span>📎 '+esc(a.name)+'</span><span><button class="button secondary" type="button" data-download="'+i+'">Baixar</button> <button class="button secondary" type="button" data-remove="'+i+'">Remover</button></span></div>').join(''):'<p class="hr-attachment-empty">Nenhum documento anexado.</p>')+'</div><fieldset class="hr-pdf-choice"><legend>Gerar ficha em PDF</legend><label><input type="radio" name="includeAttachments" value="no" checked> Somente a ficha</label><label><input type="radio" name="includeAttachments" value="yes"> Ficha com anexos (PDFs e imagens)</label></fieldset></section><footer class="hr-editor-footer"><button type="button" class="button secondary" data-edit>Editar dados</button><button type="button" class="button primary" data-pdf>Gerar PDF</button><button type="button" class="button secondary" data-close>Fechar</button></footer>';document.body.append(d);d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{d.close();d.remove()});
d.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(String(employee[b.dataset.copy]||''));notify('Campo copiado.')}catch(e){notify('Não foi possível copiar.')}});d.querySelector('[data-edit]').onclick=()=>{d.close();d.remove();if(editOriginal)editOriginal();else notify('Edição não disponível nesta sessão.')};
d.querySelector('[data-upload]').onchange=async e=>{if(!root.EngefexAccess?.canWrite('hr-employees'))return notify('Sem permissão para anexar.');const files=Array.from(e.target.files||[]);if(!files.length)return;try{const prepared=await Promise.all(files.map(f=>root.LocalFiles.prepare(f)));await root.LocalFiles.put(prepared);const next=structuredClone(s),target=next.hrEmployees.find(x=>x.id===employee.id);target.attachments=[...(target.attachments||[]),...prepared.map(({id,name,type})=>({id,name,type}))];await persist(next,'Documentos anexados à ficha.');d.close();d.remove();render()}catch(err){notify(err.message||'Falha ao anexar.')}};
d.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{await root.LocalFiles.download(all[Number(b.dataset.download)].id)}catch(err){notify(err.message)}});
d.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(!root.EngefexAccess?.canWrite('hr-employees'))return notify('Sem permissão para remover.');const i=Number(b.dataset.remove);if(!confirm('Remover o vínculo com '+all[i].name+'?'))return;const next=structuredClone(s),target=next.hrEmployees.find(x=>x.id===employee.id);target.attachments=(target.attachments||[]).filter(a=>a.id!==all[i].id);try{await persist(next,'Anexo removido da ficha.');d.close();d.remove();render()}catch(err){notify(err.message)}});
d.querySelector('[data-pdf]').onclick=async()=>{const b=d.querySelector('[data-pdf]');b.disabled=true;b.textContent='Gerando PDF...';try{await generatePdf(employee,d.querySelector('[name=includeAttachments]:checked').value==='yes')}catch(err){notify(err.message)}finally{b.disabled=false;b.textContent='Gerar PDF'}};d.showModal();}
};
})(window);